use crate::aap::caps::kb_read;

const MAX_QUESTION_CHARS: usize = 512;

struct Node;

/// Bound a string to at most `max` Unicode scalar values, matching Python's
/// `len()` on `str`. Never splits a UTF-8 sequence.
fn bound_chars(s: String, max: usize) -> String {
    match s.char_indices().nth(max) {
        Some((byte_idx, _)) => s[..byte_idx].to_string(),
        None => s,
    }
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let q = query.query;
        let intent = q.intent;

        // The requires-clause already bounds the question; re-bound it anyway so
        // the ensures-clause holds by construction rather than by assumption.
        let question = bound_chars(q.question, MAX_QUESTION_CHARS);

        // Build the lookup key from the bounded question plus any extracted entities.
        let mut lookup_key = question.clone();
        for entity in q.entities.iter() {
            let e = entity.trim();
            if !e.is_empty() {
                if !lookup_key.is_empty() {
                    lookup_key.push(' ');
                }
                lookup_key.push_str(e);
            }
        }

        let mut knowledge: Vec<String> = kb_read::lookup(&lookup_key)
            .into_iter()
            .filter(|entry| !entry.trim().is_empty())
            .collect();

        // Fall back to the question alone if the widened key found nothing.
        if knowledge.is_empty() && lookup_key != question && !question.is_empty() {
            knowledge = kb_read::lookup(&question)
                .into_iter()
                .filter(|entry| !entry.trim().is_empty())
                .collect();
        }

        // Ensure `knowledge` is present (non-empty) on every output.
        if knowledge.is_empty() {
            knowledge.push(String::from(
                "No relevant knowledge base entries were found for this question.",
            ));
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
